package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/reports") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class ReportController{private final JdbcClient db;public ReportController(JdbcClient db){this.db=db;}
 @GetMapping Map<String,Object> report(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);var result=new LinkedHashMap<String,Object>();result.put("lastMonth",db.sql("select coalesce(sum(total),0) sales,count(*) orders,coalesce(sum(amount_paid),0) collected from amcservice.orders where tenant_id=:t and created_at>=date_trunc('month',current_date)-interval '1 month' and created_at<date_trunc('month',current_date)").param("t",u.tenantId()).query().listOfRows().getFirst());result.put("trending",db.sql("select oi.description,oi.item_kind,sum(oi.quantity) quantity,sum((oi.unit_price-oi.discount)*oi.quantity) revenue from amcservice.order_items oi join amcservice.orders o on o.id=oi.order_id where o.tenant_id=:t and o.created_at>=current_date-interval '90 days' group by oi.description,oi.item_kind order by quantity desc,revenue desc limit 10").param("t",u.tenantId()).query().listOfRows());result.put("chefs",db.sql("select e.id,e.name,b.name branch_name,count(distinct jc.job_card_id) jobs,count(distinct case when j.status='COMPLETED' then j.id end) completed from amcservice.employees e join amcservice.branches b on b.id=e.branch_id left join amcservice.job_card_chefs jc on jc.employee_id=e.id left join amcservice.job_cards j on j.id=jc.job_card_id where e.tenant_id=:t and e.job_role='CHEF' group by e.id,b.name order by jobs desc,e.name").param("t",u.tenantId()).query().listOfRows());return result;}}
